-- | One item of a tuple, with its position in what is said when it is wrong.
at :: FromJson a => Int -> Json -> Either String a
at n = within ("." ++ show n) . fromJson

-- | Says where in a value something went wrong.
within :: String -> Either String a -> Either String a
within place = either (\e -> Left (place ++ ": " ++ e)) Right

-- ---------------------------------------------------------------------------
-- Base64

alphabet :: ByteString
alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

encodeBase64 :: ByteString -> Text
encodeBase64 = T.pack . go . BS.unpack
  where
    sextet :: Int -> Char
    sextet n = chr (fromIntegral (BS.index alphabet (n .&. 63)))
    go (a : b : c : rest) =
      let n = fromIntegral a `shiftL` 16 .|. fromIntegral b `shiftL` 8 .|. fromIntegral c :: Int
       in sextet (n `shiftR` 18) : sextet (n `shiftR` 12) : sextet (n `shiftR` 6) : sextet n : go rest
    go [a, b] =
      let n = fromIntegral a `shiftL` 16 .|. fromIntegral b `shiftL` 8 :: Int
       in [sextet (n `shiftR` 18), sextet (n `shiftR` 12), sextet (n `shiftR` 6), '=']
    go [a] =
      let n = fromIntegral a `shiftL` 16 :: Int
       in [sextet (n `shiftR` 18), sextet (n `shiftR` 12), '=', '=']
    go [] = []

decodeBase64 :: Text -> Either String ByteString
decodeBase64 t
  | T.length t `mod` 4 /= 0 = Left "base64 text comes in groups of four"
  | otherwise = BS.pack . concat <$> traverse group (zip [1 :: Int ..] (chunks (T.unpack t)))
  where
    groups = T.length t `div` 4
    chunks [] = []
    chunks s = let (g, r) = splitAt 4 s in g : chunks r
    group (i, g) = do
      let padding = if i == groups then length (takeWhile (== '=') (reverse g)) else 0
      if padding > 2
        then Left "too much padding"
        else do
          sextets <- traverse (value' padding) (zip [0 :: Int ..] g)
          let n = foldl (\acc s -> acc `shiftL` 6 .|. s) 0 sextets :: Int
              bytes = [fromIntegral (n `shiftR` 16), fromIntegral (n `shiftR` 8), fromIntegral n] :: [Word8]
          Right (take (3 - padding) bytes)
    value' padding (j, c)
      | j >= 4 - padding = if c == '=' then Right 0 else Left ("`" ++ [c] ++ "` is not base64")
      | otherwise = case BS.elemIndex (fromIntegral (ord c)) alphabet of
          Just ix | ord c < 128 -> Right ix
          _ -> Left ("`" ++ [c] ++ "` is not base64")

-- ---------------------------------------------------------------------------
-- What generated instances are built from

-- | An object, leaving out what is absent.
object :: [(Text, Maybe Json)] -> Json
object fields = JObject (Map.fromList [(k, v) | (k, Just v) <- fields])

-- | A field. One that holds nothing -- an optional that is absent, a null, an
-- `any` with nothing in it -- is left out rather than written as null, since
-- absence has one representation.
field :: ToJson a => Text -> a -> (Text, Maybe Json)
field k v = case toJson v of
  JNull -> (k, Nothing)
  json -> (k, Just json)

-- | The members of an object, or what was found instead.
asObject :: Text -> Json -> Either String (Map Text Json)
asObject _ (JObject o) = Right o
asObject what j = Left (expected ("a " ++ T.unpack what ++ " (an object)") j)

-- | A field that has to be there.
required :: FromJson a => Text -> Map Text Json -> Either String a
required k o = case Map.lookup k o of
  Nothing -> Left ("missing field `" ++ T.unpack k ++ "`")
  Just v -> within ("field `" ++ T.unpack k ++ "`") (fromJson v)

-- | A field that may be left out, which reads as null.
optional :: FromJson a => Text -> Map Text Json -> Either String a
optional k o = within ("field `" ++ T.unpack k ++ "`") (fromJson (Map.findWithDefault JNull k o))

-- | One alternative of a tagged sum: the tag beside what it carries.
variant :: Text -> Maybe Json -> Json
variant tag carried = object [("$tag", Just (JString tag)), ("value", carried >>= nonNull)]
  where
    nonNull JNull = Nothing
    nonNull v = Just v

-- | The tag of a tagged sum, and what it carries if anything.
asVariant :: Text -> Json -> Either String (Text, Maybe Json)
asVariant what j = do
  o <- asObject what j
  case Map.lookup "$tag" o of
    Just (JString tag) -> Right (tag, Map.lookup "value" o)
    _ -> Left ("a " ++ T.unpack what ++ " needs a `$tag` that is text")

-- | What a variant carries. A payload that may be absent can be left out.
payload :: FromJson a => Text -> Maybe Json -> Either String a
payload tag carried = within ("variant `" ++ T.unpack tag ++ "`") (fromJson (maybe JNull id carried))

unknownTag :: Text -> Text -> String
unknownTag what tag = show tag ++ " is not a variant of " ++ T.unpack what

-- | The text a name is written as.
asText :: Text -> Json -> Either String Text
asText _ (JString s) = Right s
asText what j = Left (expected ("a " ++ T.unpack what ++ " (a string)") j)

unknownName :: Text -> Text -> String
unknownName what name = show name ++ " is not one of the " ++ T.unpack what

-- | The first alternative of an untagged union that reads.
firstOf :: Text -> [Either String a] -> Either String a
firstOf what attempts = case [x | Right x <- attempts] of
  x : _ -> Right x
  [] -> Left ("matches none of the alternatives of " ++ T.unpack what)
